import unittest

import solution


class ParseCanvasSizeTests(unittest.TestCase):
    def test_normal_and_optional_whitespace(self):
        self.assertEqual(solution.parse_canvas_size("640x480"), (640, 480))
        self.assertEqual(solution.parse_canvas_size("  12  x  34 \n"), (12, 34))

    def test_boundaries_and_leading_zeroes(self):
        self.assertEqual(solution.parse_canvas_size("1x100000"), (1, 100000))
        self.assertEqual(solution.parse_canvas_size("00001x00002"), (1, 2))

    def test_non_string_is_type_error(self):
        for value in (None, 12, b"1x2"):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    solution.parse_canvas_size(value)

    def test_underscores_and_non_ascii_digits_are_rejected(self):
        for text in ("1_000x2", "1x2_0", "١x2", "1x２"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    solution.parse_canvas_size(text)

    def test_malformed_forms(self):
        malformed = [
            "", "   ", "1X2", "1*2", "1xx2", "1x", "x2",
            "+1x2", "-1x2", "1.0x2", "1 0x2", "1,000x2", "1x2x3",
        ]
        for text in malformed:
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    solution.parse_canvas_size(text)

    def test_zero_negative_and_out_of_range(self):
        for text in ("0x1", "1x0", "-1x2", "100001x1", "1x100001"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    solution.parse_canvas_size(text)


if __name__ == "__main__":
    unittest.main()

